export interface DB {
  patients: Patient[];
  calls: CallRecord[];
  dialogs: Dialog[];
  appointments: Appt[];
}

// ─────────────────────────────────────────────── seed

let seq = 1000;
/**
 * Идентификатор для новой строки. Обязательно случайный, а не порядковый:
 * счётчик сбрасывается при каждой загрузке страницы, и второй ответ в диалоге
 * получал id, уже занятый в базе, — запись падала на уникальном ключе, а
 * администратор видел «не удалось отправить» без объяснения.
 */
function uid(prefix: string): string {
  seq += 1;
  const rand =
    typeof crypto !== "undefined" && "randomUUID" in crypto
      ? crypto.randomUUID().slice(0, 8)
      : Math.random().toString(36).slice(2, 10);
  return `${prefix}-${seq}-${rand}`;
}
function phone(e164: string, opts: Partial<Phone> = {}): Phone {
  return {
    id: uid("ph"),
    e164,
    pretty: formatPhone(e164),
    label: null,
    isPrimary: false,
    whatsapp: false,
    ...opts,
  };
}

/**
 * Пустое начальное состояние.
 *
 * Здесь раньше лежали выдуманные пациенты и диалоги (Гринберг, Белов,
 * Чернышёва). Они рисовались до загрузки настоящих данных и оставались на
 * экране, если загрузка не дошла, — администратор видел в инбоксе людей,
 * которых в клинике нет. Настоящие данные приходят гидрацией из БД.
 */
const INITIAL: DB = {
  patients: [],
  calls: [],
  dialogs: [],
  appointments: [],
};


// ─────────────────────────────────────────────── реактивность

let db: DB = INITIAL;
const listeners = new Set<() => void>();

function commit(next: DB) {
  db = next;
  listeners.forEach((l) => l());
}
function subscribe(l: () => void) {
  listeners.add(l);
  return () => {
    listeners.delete(l);
  };
}
function getSnapshot(): DB {
  return db;
}
/**
 * Серверный снимок — всегда исходный INITIAL (стабильная ссылка). SSR и первый
 * клиентский рендер видят одинаковые данные, поэтому гидрация не расходится;
 * затем стор обновляется данными из БД уже после гидрации.
 */
function getServerSnapshot(): DB {
  return INITIAL;
}

/** Реактивное чтение стора в клиентских компонентах. */
export function useDb(): DB {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

/** Разовое чтение без подписки. */
export function getDb(): DB {
  return db;
}

/**
 * Гидрация пациентов из БД (§4 — единый источник правды). Идентичность,
 * телефоны, заметки и связи берём из БД; курсы/визиты/переписку сохраняем из
 * текущего стора (мигрируют со своими подсистемами). Пациенты, которых в БД нет
 * (мягко удалённые), из стора уходят.
 */
/**
 * Обновить пациентов в сторе.
 *
 * Записи ДОБАВЛЯЮТСЯ к тем, что уже есть, а не заменяют их. Прежде список
 * пересобирался из переданных записей целиком: карточка догружала одного
 * пациента — и в списке оставался он один, до перезагрузки страницы. Пустой
 * список пациентов при полутора тысячах в базе выглядит как потеря данных, и
 * администратор справедливо считает, что платформа сломалась.
 */
/**
 * Когда карточку пациента правили руками — по каждой карточке отдельно.
 *
 * Карточка догружается с сервера в двух местах сразу (страница и сам блок
 * карточки), и ответ, начатый ДО правки, приходил после неё — со старым
 * списком отметок. На экране это выглядело так: пометку добавили, она
 * появилась и через мгновение исчезла, а вернулась через минуту, на
 * следующем круге обновления. Со снятием — наоборот: снятая пометка
 * возвращалась. Ровно это и есть «добавляются и удаляются с багами и
 * задержкой».
 *
 * Поэтому у гидрации есть время запроса: ответ, отправленный раньше местной
 * правки, списки отметок, номеров и связей не трогает. Он всё равно принесёт
 * имя, визиты и остальное — устаревшим оказывается только то, что человек
 * только что менял.
 */
const patientWrites = new Map<string, number>();

export function markPatientWrite(patientId: string) {
  patientWrites.set(patientId, Date.now());
}

export function hydratePatients(records: PatientRecord[], requestedAt: number = Date.now()) {
  const byId = new Map(db.patients.map((p) => [p.id, p]));
  const patients: Patient[] = records.map((r) => {
    const existing = byId.get(r.id);
    const phones: Phone[] = r.phones.map((ph) => ({
      id: ph.id,
      e164: ph.e164,
      pretty: formatPhone(ph.e164),
      label: ph.label,
      isPrimary: ph.isPrimary,
      whatsapp: ph.whatsapp,
    }));
    const notes: Note[] = r.notes.map((n) => ({
      id: n.id,
      kind: n.kind,
      text: n.text,
      createdAt: existing?.notes.find((x) => x.id === n.id)?.createdAt ?? "сегодня",
      resolved: n.resolved,
    }));
    const relations: Relation[] = r.relations.map((rl) => ({
      id: rl.id,
      relatedPatientId: rl.relatedPatientId,
      kind: rl.kind,
    }));
    /**
     * История визитов приходит только с карточкой пациента: в списке её не
     * запрашивают, чтобы не тянуть тысячи строк. Поэтому отсутствие поля
     * означает «не спрашивали», а не «визитов нет», — иначе открытая карточка
     * теряла бы историю при обновлении списка.
     */
    const visits: Visit[] = r.visits ?? existing?.visits ?? [];

    if (existing) {
      /** Правили после того, как этот ответ ушёл, — местное новее. */
      const stale = (patientWrites.get(r.id) ?? 0) > requestedAt;
      return {
        ...existing,
        firstSeenAt: r.firstSeenAt ?? existing.firstSeenAt,
        visitStage: r.visitStage ?? existing.visitStage,
        name: r.name || existing.name,
        source: r.source ?? existing.source,
        sourceDerived: r.sourceDerived,
        phones: stale ? existing.phones : phones,
        notes: stale ? existing.notes : notes,
        relations: stale ? existing.relations : relations,
        visits,
      };
    }
    return {
      id: r.id,
      name: r.name,
      bornYear: null,
      firstSeen: r.firstSeenToday ? "сегодня" : "ранее",
      firstSeenAt: r.firstSeenAt,
      visitStage: r.visitStage,
      source: r.source ?? "—",
      sourceDerived: r.sourceDerived,
      channel: "phone",
      phones,
      notes,
      relations,
      courses: [],
      visits,
      messages: [],
    };
  });
  /**
   * Пришедшие записи кладём поверх прежних, порядок сохраняем: список
   * отсортирован сервером, и переставлять его от того, что открыли карточку,
   * нельзя.
   */
  const updated = new Map(patients.map((p) => [p.id, p]));
  const merged = db.patients.map((p) => updated.get(p.id) ?? p);
  for (const p of patients) if (!byId.has(p.id)) merged.push(p);

  commit({ ...db, patients: merged });
}

/**
 * Гидрация диалогов из БД (Conversation + Message). Ядро — сообщения, статус,
 * пациент, канал — из БД; UI-поля (черновик агента, таймер окна, причина
 * эскалации, «непрочитано») сохраняем из текущего диалога по id.
 */
/**
 * Когда переписку правили руками — по каждой отдельно.
 *
 * Список диалогов тянется раз в шесть секунд, и ответ, ушедший ДО нажатия,
 * приходит после него — со старым состоянием. Выключатель агента возвращался в
 * прежнее положение сам, только что отправленное сообщение пропадало из
 * переписки на несколько секунд и появлялось снова. В базе при этом всё было
 * записано верно: врал экран.
 *
 * Та же защита, что у карточки пациента: ответ старше местной правки не
 * трогает то, что человек только что менял.
 */
const dialogWrites = new Map<string, number>();

export function markDialogWrite(dialogId: string) {
  dialogWrites.set(dialogId, Date.now());
}

export function hydrateDialogs(records: DialogRecord[], requestedAt: number = Date.now()) {
  const byId = new Map(db.dialogs.map((d) => [d.id, d]));
  const dialogs: Dialog[] = records.map((r) => {
    const existing = byId.get(r.id);
    /** Правили после того, как этот ответ ушёл, — местное новее. */
    const stale = (dialogWrites.get(r.id) ?? 0) > requestedAt;
    const messages: Message[] = r.messages.map((m) => ({
      id: m.id,
      from: m.from,
      text: m.text,
      at: m.at,
      attachments: m.attachments ?? [],
      delivery: m.delivery,
      failureReason: m.failureReason,
      replyToPreview: m.replyToPreview,
      edited: m.edited,
      canRecall: m.canRecall,
    }));
    /**
     * Своё только что отправленное сообщение сервер мог ещё не отдать —
     * дописываем его к пришедшим, а не подменяем список целиком: иначе оно
     * исчезает из переписки на несколько секунд и появляется снова.
     */
    const known = new Set(messages.map((m) => m.id));
    const merged =
      stale && existing
        ? [...messages, ...existing.messages.filter((m) => !known.has(m.id))]
        : messages;

    return {
      id: r.id,
      name: r.name ?? existing?.name ?? "Без имени",
      channel: r.channel,
      patientId: r.patientId,
      phone: r.phone,
      preview: r.preview,
      at: r.at,
      /**
       * Состояние берём с сервера: раньше оно бралось из мока и для диалогов
       * из базы всегда было пустым — фильтр «Нужен ответ» не находил ничего.
       *
       * Пока отметка прочтения не легла в базу, держим её своей: список
       * тянется каждые шесть секунд и приносит снимок, сделанный до записи.
       * Точка гасла на мгновение и загоралась снова.
       */
      unread: readMarks.staysRead(r.id, messages[messages.length - 1]?.id ?? null) ? false : r.unread,
      escalationReason: r.escalationReason ?? undefined,
      agentDraft: existing?.agentDraft,
      /**
       * Выключатель агента и статус берём с сервера — кроме случая, когда их
       * только что меняли руками.
       *
       * Диалог здесь пересобирается по полям, и не перечисленное теряется:
       * поле забыли — и кнопка возвращалась в исходное через шесть секунд.
       * Теперь то же самое умеет сделать и ответ сервера, ушедший ДО нажатия;
       * от этого спасает отметка местной правки.
       */
      agentDisabled: stale && existing ? existing.agentDisabled : r.agentDisabled,
      agentPausedUntil: r.agentPausedUntil,
      windowOpen: r.windowOpen,
      windowMinutesLeft: r.windowMinutesLeft,
      totalMessages: r.totalMessages,
      status: stale && existing ? existing.status : r.status,
      waitingSince: r.waitingSince,
      unreadCount: r.unreadCount,
      firstTime: r.firstTime,
      practice: r.practice,
      reminder: r.reminder,
      scheduled: r.scheduled,
      noteCount: r.noteCount,
      messages: merged,
    };
  });
  commit({ ...db, dialogs });
}

/** Гидрация расписания из БД (проекция Appointment) — единый источник. */
export function hydrateAppointments(appts: Appt[]) {
  commit({ ...db, appointments: appts });
}

/**
 * Курсы пациентов из базы.
 *
 * Приходят отдельным списком, а не внутри карточки: курс нужен экранам, где
 * карточка не открыта — «Курсы», аналитика пациентов, строка «выпали из курса»
 * на «Сегодня». Раньше все они читали пустой список и молча ничего не
 * показывали.
 */
export function hydrateCourses(records: (Course & { patientId: string })[]) {
  const byPatient = new Map<string, Course[]>();
  for (const { patientId, ...course } of records) {
    byPatient.set(patientId, [...(byPatient.get(patientId) ?? []), course]);
  }
  commit({
    ...db,
    patients: db.patients.map((p) => ({ ...p, courses: byPatient.get(p.id) ?? [] })),
  });
}

// ─────────────────────────────────────────────── производные

export function primaryPhone(p: Patient): Phone | null {
  return p.phones.find((ph) => ph.isPrimary) ?? p.phones[0] ?? null;
}

export function patientTags(p: Patient): string[] {
  const tags: string[] = [];
  /**
   * Метка пути — по состоявшимся визитам, а не по дате контакта. Прежде у
   * пациента, пришедшего не сегодня, метки не было вовсе: ни «первичный», ни
   * «повторный», пустое место в карточке и в списке.
   */
  if (p.visitStage === "primary") tags.push("первичный");
  else if (p.visitStage === "repeat") tags.push("повторный");
  else if (p.visitStage === "new") tags.push("без визитов");
  else if (p.firstSeen === "сегодня") tags.push("первичный");
  if (p.courses.some((c) => c.status === "active")) tags.push("на курсе");
  if (p.courses.some((c) => c.status === "stalled")) tags.push("выпал из курса");
  if (p.notes.some((n) => n.kind === "NO_CONSENT" && !n.resolved)) tags.push("без согласия");
  return tags;
}

export function activeNotes(p: Patient): Note[] {
  return p.notes.filter((n) => !n.resolved);
}

export function findPatient(id: string): Patient | undefined {
  return db.patients.find((p) => p.id === id);
}

export function patientCalls(id: string): CallRecord[] {
  return db.calls.filter((c) => c.patientId === id);
}

/** Поиск по имени и всем номерам пациента. */
export function searchPatients(query: string, patients: Patient[] = db.patients): Patient[] {
  const q = query.trim().toLowerCase();
  if (!q) return patients;
  const digits = q.replace(/\D/g, "");
  return patients.filter((p) => {
    if (p.name.toLowerCase().includes(q)) return true;
    if (digits.length >= 2) {
      return p.phones.some((ph) => ph.e164.replace(/\D/g, "").includes(digits));
    }
    return false;
  });
}

// ─────────────────────────────────────────────── мутаторы

/**
 * Что делать, когда запись в базу не удалась.
 *
 * Все изменения здесь идут «сквозь»: сначала меняется экран, затем база. Пока
 * неудачу гасил пустой `catch`, экран оставался с изменением, которого в базе
 * нет, — отметка «пришёл» не доезжала, а выручка считалась по базе. Теперь
 * такая неудача видна человеку, а не только в консоли браузера.
 *
 * В сообщение попадает только действие и причина: ни имён, ни телефонов, ни
 * текстов сообщений (§7).
 */
export function writeFailed(action: string): (e: unknown) => void {
  return (e: unknown) => {
    const reason = (e as Error)?.message ?? String(e);
    console.error(`[запись] ${action}: ${reason}`);
    // Не сохранилось из-за старой сборки — вкладку надо обновить, а не
    // повторять действие: следующее упадёт так же.
    reportMaybeStale(e);
    if (typeof window !== "undefined") {
      window.dispatchEvent(new CustomEvent("clinic:write-failed", { detail: { action, reason } }));
    }
  };
}

/**
 * Записать с одной тихой повторной попыткой.
 *
 * Между экраном и базой лежит сеть и приложение, которое иногда
 * перезапускается: часть неудач проходит сама через секунду. Показывать их
 * человеку незачем — он не может «повторить действие» лучше, чем это сделаем
 * мы. Не прошло и со второго раза — тогда говорим, и говорим, что теперь
 * делать (`hint`), а не «повторите действие».
 *
 * **Повторяем только то, что можно повторить без последствий**: установку
 * значения, снятие пометки, переключатель. Создание — заметку, номер, карточку,
 * сообщение — не повторяем никогда: первый запрос мог дойти, и человек получит
 * два. Такие вызовы остаются на `writeFailed`.
 */
const RETRY_WRITE_MS = 1200;

export function persist(action: string, run: () => Promise<unknown>, hint?: string) {
  void run().catch((first: unknown) => {
    reportMaybeStale(first);
    setTimeout(() => {
      void run().catch((e: unknown) => {
        const reason = (e as Error)?.message ?? String(e);
        console.error(`[запись] ${action}: ${reason}`);
        reportMaybeStale(e);
        if (typeof window !== "undefined") {
          window.dispatchEvent(
            new CustomEvent("clinic:write-failed", { detail: { action, reason, hint } }),
          );
        }
      });
    }, RETRY_WRITE_MS);
  });
}

function replacePatient(id: string, fn: (p: Patient) => Patient) {
  commit({ ...db, patients: db.patients.map((p) => (p.id === id ? fn(p) : p)) });
}

export function addPatient(input: { name: string; phone: string; source?: string }): Patient {
  const e164 = normalizePhone(input.phone);
  const ph = e164 ? phone(e164, { isPrimary: true }) : null;
  const created: Patient = {
    id: uid("p"),
    name: input.name.trim(),
    bornYear: null,
    firstSeen: "сегодня",
    source: input.source ?? "Вручную",
    channel: "phone",
    phones: ph ? [ph] : [],
    notes: [],
    relations: [],
    courses: [],
    visits: [],
    messages: [],
  };
  commit({ ...db, patients: [created, ...db.patients] });
  void createPatient({
    id: created.id,
    name: created.name,
    source: input.source ?? null,
    phoneId: ph?.id,
    e164: e164 ?? null,
  }).catch(writeFailed("не удалось завести карточку пациента"));
  return created;
}

export function updatePatient(id: string, patch: Partial<Pick<Patient, "name" | "bornYear" | "source">>) {
  replacePatient(id, (p) => ({ ...p, ...patch }));
  if (patch.name !== undefined || patch.source !== undefined) {
    markPatientWrite(id);
    void updatePatientDb(id, { name: patch.name, source: patch.source })
      .then(() => refreshPatient(id))
      .catch(writeFailed("не удалось сохранить карточку пациента"));
  }
}

/**
 * Источник визита из карточки пациента.
 *
 * Та же отметка MANUAL, что и в списке дня, — просто дотянуться до старого
 * визита можно только отсюда. Пустой код снимает отметку: «не знаю» честнее
 * наугад выбранного канала.
 */
export function setVisitSource(
  patientId: string,
  visitId: string,
  code: string | null,
  title: string | null,
) {
  replacePatient(patientId, (p) => ({
    ...p,
    visits: p.visits.map((v) =>
      v.id === visitId
        ? { ...v, sourceCode: code, sourceTitle: title, sourceConfidence: code ? "MANUAL" : "UNKNOWN" }
        : v,
    ),
  }));
  void setApptSourceDb(visitId, code).catch(writeFailed("источник визита не сохранён"));
}

export function removePatient(id: string) {
  commit({
    ...db,
    patients: db.patients
      .filter((p) => p.id !== id)
      // Чистим родственные ссылки на удалённого — иначе повиснут.
      .map((p) => ({ ...p, relations: p.relations.filter((r) => r.relatedPatientId !== id) })),
    calls: db.calls.map((c) => (c.patientId === id ? { ...c, patientId: null } : c)),
  });
  void softDeletePatient(id).catch(writeFailed("не удалось удалить карточку пациента"));
}

/** Добавить номер. Возвращает false, если номер не распознан. */
export function addPhone(patientId: string, raw: string): boolean {
  const e164 = normalizePhone(raw);
  if (!e164) return false;
  const p = findPatient(patientId);
  if (p?.phones.some((ph) => ph.e164 === e164)) return true;
  const isFirst = (p?.phones.length ?? 0) === 0;
  const ph = phone(e164, { isPrimary: isFirst });
  replacePatient(patientId, (cur) =>
    cur.phones.some((x) => x.e164 === e164) ? cur : { ...cur, phones: [...cur.phones, ph] },
  );
  markPatientWrite(patientId);
  void addPhoneDb({ id: ph.id, patientId, e164, isPrimary: isFirst })
    .then(() => refreshPatient(patientId))
    .catch(writeFailed("не удалось добавить номер"));
  return true;
}

export function removePhone(patientId: string, phoneId: string) {
  const p = findPatient(patientId);
  if (!p) return;
  const rest = p.phones.filter((ph) => ph.id !== phoneId);
  let newPrimaryId: string | null = null;
  if (rest.length > 0 && !rest.some((ph) => ph.isPrimary)) newPrimaryId = rest[0].id;
  replacePatient(patientId, (cur) => {
    const r = cur.phones.filter((ph) => ph.id !== phoneId);
    if (r.length > 0 && !r.some((ph) => ph.isPrimary)) r[0] = { ...r[0], isPrimary: true };
    return { ...cur, phones: r };
  });
  markPatientWrite(patientId);
  void removePhoneDb(phoneId, newPrimaryId)
    .then(() => refreshPatient(patientId))
    .catch(writeFailed("не удалось убрать номер"));
}

export function setPrimaryPhone(patientId: string, phoneId: string) {
  replacePatient(patientId, (p) => ({
    ...p,
    phones: p.phones.map((ph) => ({ ...ph, isPrimary: ph.id === phoneId })),
  }));
  markPatientWrite(patientId);
  void setPrimaryPhoneDb(patientId, phoneId)
    .then(() => refreshPatient(patientId))
    .catch(writeFailed("не удалось сменить основной номер"));
}

export function toggleWhatsapp(patientId: string, phoneId: string) {
  const p = findPatient(patientId);
  const next = !p?.phones.find((ph) => ph.id === phoneId)?.whatsapp;
  replacePatient(patientId, (cur) => ({
    ...cur,
    phones: cur.phones.map((ph) => (ph.id === phoneId ? { ...ph, whatsapp: !ph.whatsapp } : ph)),
  }));
  markPatientWrite(patientId);
  void toggleWhatsappDb(phoneId, next)
    .then(() => refreshPatient(patientId))
    .catch(writeFailed("не удалось отметить WhatsApp у номера"));
}

export function addNote(patientId: string, kind: NoteKind, text: string) {
  const note: Note = { id: uid("n"), kind, text: text.trim(), createdAt: "сегодня", resolved: false };
  replacePatient(patientId, (p) => ({ ...p, notes: [...p.notes, note] }));
  markPatientWrite(patientId);
  void addNoteDb({ id: note.id, patientId, kind, text: note.text })
    .then(() => refreshPatient(patientId))
    .catch(writeFailed("не удалось сохранить пометку"));
}

export function resolveNote(patientId: string, noteId: string) {
  replacePatient(patientId, (p) => ({
    ...p,
    notes: p.notes.map((n) => (n.id === noteId ? { ...n, resolved: true } : n)),
  }));
  markPatientWrite(patientId);
  void resolveNoteDb(noteId)
    .then(() => refreshPatient(patientId))
    .catch(writeFailed("не удалось снять пометку"));
}

/**
 * Перечитать карточку сразу после записи.
 *
 * Раньше правка ждала общего круга обновления — минуту. За эту минуту экран
 * показывал местное состояние, и если запись не прошла, человек об этом не
 * знал: он видел свою пометку и уходил. Теперь ответ сервера приходит через
 * доли секунды и подтверждает (или опровергает) то, что на экране.
 */
function refreshPatient(patientId: string) {
  const at = Date.now();
  void getPatientRecord(patientId)
    .then((record) => {
      if (record) hydratePatients([record], at);
    })
    .catch(() => {
      // Не перечиталось — на экране остаётся местное состояние, а неудача
      // самой записи показывается отдельно.
    });
}

export function addRelation(patientId: string, relatedPatientId: string, kind: RelationKind) {
  if (patientId === relatedPatientId) return;
  const p = findPatient(patientId);
  if (p?.relations.some((r) => r.relatedPatientId === relatedPatientId)) return;
  const rel: Relation = { id: uid("r"), relatedPatientId, kind };
  replacePatient(patientId, (cur) =>
    cur.relations.some((r) => r.relatedPatientId === relatedPatientId)
      ? cur
      : { ...cur, relations: [...cur.relations, rel] },
  );
  markPatientWrite(patientId);
  void addRelationDb({ id: rel.id, patientId, relatedPatientId, kind })
    .then(() => refreshPatient(patientId))
    .catch(writeFailed("не удалось связать карточки"));
}

export function removeRelation(patientId: string, relationId: string) {
  replacePatient(patientId, (p) => ({
    ...p,
    relations: p.relations.filter((r) => r.id !== relationId),
  }));
  markPatientWrite(patientId);
  void removeRelationDb(relationId)
    .then(() => refreshPatient(patientId))
    .catch(writeFailed("не удалось убрать связь карточек"));
}

/**
 * Занести звонок. Звонок — обращение наравне с сообщением (§3.4): привязываем к
 * пациенту по номеру, если найден; иначе можно завести нового. Возвращает id
 * пациента, если удалось связать.
 */
export function logCall(input: {
  phone: string;
  direction: "in" | "out";
  serviceInterest?: string | null;
  source?: string | null;
  note?: string;
  patientId?: string | null;
  createNamed?: string; // если задано и пациент не найден — создать с этим именем
}): { callId: string; patientId: string | null } {
  const e164 = normalizePhone(input.phone) ?? input.phone;
  let patientId = input.patientId ?? null;

  if (!patientId) {
    const match = db.patients.find((p) => p.phones.some((ph) => ph.e164 === e164));
    if (match) patientId = match.id;
  }

  let patients = db.patients;
  if (!patientId && input.createNamed && input.createNamed.trim().length > 0) {
    const created: Patient = {
      id: uid("p"),
      name: input.createNamed.trim(),
      bornYear: null,
      firstSeen: "сегодня",
      source: input.source ?? "Звонок",
      channel: "phone",
      phones: normalizePhone(input.phone) ? [phone(e164, { isPrimary: true })] : [],
      notes: [],
      relations: [],
      courses: [],
      visits: [],
      messages: [],
    };
    patients = [created, ...patients];
    patientId = created.id;
  }

  const call: CallRecord = {
    id: uid("call"),
    at: "только что",
    patientId,
    phone: normalizePhone(input.phone) ? formatPhone(e164) : input.phone,
    direction: input.direction,
    serviceInterest: input.serviceInterest ?? null,
    source: input.source ?? null,
    note: (input.note ?? "").trim(),
  };
  commit({ ...db, patients, calls: [call, ...db.calls] });
  return { callId: call.id, patientId };
}

// ─────────────────────────────────────────────── диалоги

function replaceDialog(id: string, fn: (d: Dialog) => Dialog) {
  commit({ ...db, dialogs: db.dialogs.map((d) => (d.id === id ? fn(d) : d)) });
}

/** Отправить ответ вручную. Диалог переходит к человеку, черновик снимается. */
/**
 * Отправить ответ пациенту. Возвращает промис с результатом доставки: если
 * канал не принял сообщение, интерфейс обязан это показать — иначе
 * администратор уверен, что ответил, а пациент ничего не получил.
 */
export interface OutgoingAttachment {
  /** Идентификатор в хранилище: файл уже загружен через /api/upload. */
  mediaId: string;
  kind: string;
  label: string;
  href: string;
  fileName?: string;
  durationSec?: number;
}

export function sendMessage(
  dialogId: string,
  text: string,
  options: {
    files?: OutgoingAttachment[];
    replyToMessageId?: string | null;
    replyToPreview?: string | null;
  } = {},
): Promise<{ ok: boolean; error?: string }> {
  const t = text.trim();
  const files = options.files ?? [];
  if (!t && files.length === 0) return Promise.resolve({ ok: false, error: "Пустое сообщение" });
  const msg: Message = {
    id: uid("m"),
    from: "staff",
    text: t,
    at: "сейчас",
    attachments: files.map((f) => ({
      kind: f.kind,
      label: f.label,
      href: f.href,
      fileName: f.fileName,
      durationSec: f.durationSec,
    })),
    // Пока сервер не ответил — «отправляется». Не «доставлено»: доставки мы
    // ещё не видели, а нарисованная галочка хуже её отсутствия.
    delivery: "sending",
    replyToPreview: options.replyToPreview ?? undefined,
  };
  markDialogWrite(dialogId);
  replaceDialog(dialogId, (d) => ({
    ...d,
    messages: [...d.messages, msg],
    status: "human",
    unread: false,
    preview: t || files[0]?.label || "вложение",
    agentDraft: undefined,
  }));
  return sendMessageDb(dialogId, msg.id, t, {
    mediaIds: files.map((f) => f.mediaId),
    replyToMessageId: options.replyToMessageId ?? null,
  })
    .then((res) => {
      /**
       * Не ушло — показываем это прямо в переписке, а не только полосой:
       * администратор смотрит на разговор, а не на низ экрана.
       */
      replaceDialog(dialogId, (d) => ({
        ...d,
        messages: d.messages.map((m) =>
          m.id === msg.id
            ? { ...m, delivery: res.ok ? "sent" : "failed", failureReason: res.ok ? undefined : res.error }
            : m,
        ),
      }));
      return res;
    })
    .catch(() => {
      /**
       * Связь оборвалась на полпути: сообщение могло уйти, а могло и нет.
       * Пробуем один раз сами — на сервере стоит проверка по идентификатору,
       * поэтому второй отправки пациенту не будет. Не помогло — говорим
       * словами и оставляем кнопку повтора: текст при этом никуда не делся,
       * он в самом сообщении.
       */
      return new Promise<{ ok: boolean; error?: string }>((resolve) => {
        setTimeout(() => {
          void sendMessageDb(dialogId, msg.id, t, {
            mediaIds: files.map((f) => f.mediaId),
            replyToMessageId: options.replyToMessageId ?? null,
          })
            .then((res) => {
              replaceDialog(dialogId, (d) => ({
                ...d,
                messages: d.messages.map((m) =>
                  m.id === msg.id
                    ? {
                        ...m,
                        delivery: res.ok ? "sent" : "failed",
                        failureReason: res.ok ? undefined : res.error,
                      }
                    : m,
                ),
              }));
              resolve(res);
            })
            .catch(() => {
              replaceDialog(dialogId, (d) => ({
                ...d,
                messages: d.messages.map((m) =>
                  m.id === msg.id
                    ? { ...m, delivery: "failed", failureReason: "Нет связи с сервером" }
                    : m,
                ),
              }));
              resolve({ ok: false, error: "Нет связи с сервером" });
            });
        }, RESEND_DELAY_MS);
      });
    });
}

/** Пауза перед единственной автоматической повторной отправкой. */
const RESEND_DELAY_MS = 2000;

/** Отправить ещё раз то, что не ушло. Текст и файлы берутся из сообщения. */
export function resendMessage(dialogId: string, messageId: string) {
  markDialogWrite(dialogId);
  replaceDialog(dialogId, (d) => ({
    ...d,
    messages: d.messages.map((m) =>
      m.id === messageId ? { ...m, delivery: "sending", failureReason: undefined } : m,
    ),
  }));
  return resendMessageDb(messageId)
    .then((res) => {
      replaceDialog(dialogId, (d) => ({
        ...d,
        messages: d.messages.map((m) =>
          m.id === messageId
            ? { ...m, delivery: res.ok ? "sent" : "failed", failureReason: res.ok ? undefined : res.error }
            : m,
        ),
      }));
      return res;
    })
    .catch(() => {
      replaceDialog(dialogId, (d) => ({
        ...d,
        messages: d.messages.map((m) =>
          m.id === messageId ? { ...m, delivery: "failed", failureReason: "Нет связи с сервером" } : m,
        ),
      }));
      return { ok: false, error: "Нет связи с сервером" };
    });
}

/**
 * Черновики по диалогам.
 *
 * Раньше поле ввода было общим на все переписки: набранное для одного
 * пациента оставалось на экране при переходе к другому — и уходило ему же,
 * стоило нажать «Отправить». Теперь черновик привязан к диалогу.
 *
 * В памяти, а не в localStorage: в черновике бывает жалоба на здоровье, и
 * складывать её на диск браузера ради удобства нельзя (§7). Вкладку закрыли —
 * черновик пропал; переключение диалогов, ради которого всё и делалось, он
 * переживает.
 */
const drafts = new Map<string, string>();

export function draftOf(dialogId: string): string {
  return drafts.get(dialogId) ?? "";
}

export function setDraft(dialogId: string, text: string) {
  if (text) drafts.set(dialogId, text);
  else drafts.delete(dialogId);
}

/** Убрать сообщение у себя и у пациента. */
export function removeMessage(dialogId: string, messageId: string) {
  markDialogWrite(dialogId);
  return deleteMessageDb(messageId)
    .then((res) => {
      if (res.ok) {
        replaceDialog(dialogId, (d) => ({
          ...d,
          messages: d.messages.filter((m) => m.id !== messageId),
        }));
      }
      return res;
    })
    .catch(() => ({ ok: false, error: "Не удалось связаться с сервером" }));
}

/** Исправить текст уже отправленного сообщения. */
export function editMessage(dialogId: string, messageId: string, text: string) {
  markDialogWrite(dialogId);
  return editMessageDb(messageId, text)
    .then((res) => {
      if (res.ok) {
        replaceDialog(dialogId, (d) => ({
          ...d,
          messages: d.messages.map((m) => (m.id === messageId ? { ...m, text, edited: true } : m)),
        }));
      }
      return res;
    })
    .catch(() => ({ ok: false, error: "Не удалось связаться с сервером" }));
}

/**
 * Отправить шаблон.
 *
 * Отдельно от sendMessage, потому что текст шаблона — заготовка с
 * переменными, и подставляет их сервер: у него есть карточка пациента и его
 * запись. Пока подстановки не было, пациент получал «Здравствуйте, {{name}}!».
 *
 * В переписку сразу кладём заготовку с пометкой — сервер вернёт настоящий
 * текст только после отправки. Если данных не хватило, отправки не будет и
 * администратор увидит, чего именно недостаёт.
 */
export function sendTemplate(
  dialogId: string,
  templateId: string,
  title: string,
): Promise<{ ok: boolean; error?: string }> {
  const msg: Message = {
    id: uid("m"),
    from: "staff",
    text: `Шаблон «${title}»…`,
    at: "сейчас",
    attachments: [],
  };
  replaceDialog(dialogId, (d) => ({
    ...d,
    messages: [...d.messages, msg],
    status: "human",
    unread: false,
    preview: msg.text,
    agentDraft: undefined,
  }));
  return sendTemplateDb(dialogId, msg.id, templateId)
    .then((res) => {
      /**
       * Не ушло — убираем заготовку из переписки.
       *
       * Иначе в диалоге остаётся «Шаблон „…“…», которого пациент не получал.
       * Сообщение, которое не ушло, не показывается как отправленное.
       */
      if (!res.ok) {
        replaceDialog(dialogId, (d) => ({
          ...d,
          messages: d.messages.filter((m) => m.id !== msg.id),
        }));
      }
      return res;
    })
    .catch(() => {
      replaceDialog(dialogId, (d) => ({
        ...d,
        messages: d.messages.filter((m) => m.id !== msg.id),
      }));
      return { ok: false, error: "Не удалось связаться с сервером" };
    });
}

/** Вернуть диалог агенту: снять паузу и закрыть эскалацию. */
/**
 * Выключить или включить агента в диалоге — насовсем.
 *
 * Не пауза: срок у выключателя не истекает. Нужен там, где в пациентский
 * канал пишут сотрудники клиники между собой и агент отвечает им как
 * пациенту, ничего не понимая.
 */
export function setAgentEnabled(dialogId: string, enabled: boolean) {
  replaceDialog(dialogId, (d) => ({
    ...d,
    agentDisabled: !enabled,
    // Включили — разговор снова ведёт агент; выключили — статус не трогаем,
    // им распоряжается сама переписка.
    status: enabled ? "bot" : d.status,
  }));
  markDialogWrite(dialogId);
  persist(
    enabled ? "Агент не включился" : "Агент не выключился",
    () => setAgentEnabledDb(dialogId, enabled),
    "Он остался как был — нажмите кнопку ещё раз.",
  );
}

export function returnToBot(dialogId: string) {
  replaceDialog(dialogId, (d) => ({ ...d, status: "bot", escalationReason: undefined }));
  markDialogWrite(dialogId);
  persist(
    "Диалог не вернулся агенту",
    () => returnToBotDb(dialogId),
    "Разговор остался за вами — нажмите «Вернуть агенту» ещё раз.",
  );
}

/**
 * Очередь отметок прочтения.
 *
 * Единственное действие в инбоксе, которого человек не совершал: он просто
 * открыл переписку. Поэтому его неудача не идёт в `writeFailed` — просить
 * «повторите действие» тут нечего, повторяем сами (`lib/client/read-marks`).
 */
const readMarks = createReadMarks({
  send: (id) => markDialogReadDb(id),
  onFailed: (_id, reason) => {
    console.error(`[запись] отметка прочтения: ${(reason as Error)?.message ?? String(reason)}`);
    // Старая сборка — отдельный случай: там поможет только перезагрузка вкладки.
    reportMaybeStale(reason);
  },
});

/**
 * Диалог прочитан.
 *
 * Отметку нужно сохранить на сервере, а не только на экране: список тянется
 * заново каждые несколько секунд, и «непрочитано» возвращалось вместе с ним.
 * Фиолетовая точка гасла на мгновение и загоралась снова — администратор
 * перестал на неё смотреть.
 */
export function markDialogRead(dialogId: string) {
  const last = db.dialogs.find((d) => d.id === dialogId)?.messages.slice(-1)[0]?.id ?? null;
  replaceDialog(dialogId, (d) => ({ ...d, unread: false }));
  readMarks.mark(dialogId, last);
}

/**
 * Повторить отметки, которые не легли в базу.
 *
 * Зовётся с круга опроса инбокса и при возвращении в приложение: сеть моргнула
 * или сервер перезапускался — повторим сами, человека это не касается.
 */
export function flushReadMarks() {
  readMarks.flush();
}

/**
 * Массовые действия по концу смены: отметить прочитанными и закрыть.
 *
 * Экран меняется сразу, база — следом, как и у остальных записей. Неудача
 * видна человеку: «отметил десять» при десяти незаписанных отметках — это
 * ровно тот случай, когда система уверенно врёт о выполненной работе.
 */
export function markDialogsRead(ids: string[]) {
  commit({
    ...db,
    dialogs: db.dialogs.map((d) => (ids.includes(d.id) ? { ...d, unread: false, unreadCount: 0 } : d)),
  });
  persist(
    "Отметки прочтения не записались",
    () => markDialogsReadDb(ids),
    "Диалоги остались непрочитанными — отметьте ещё раз.",
  );
}

export function closeDialogs(ids: string[]) {
  commit({
    ...db,
    dialogs: db.dialogs.map((d) =>
      ids.includes(d.id)
        ? { ...d, status: "closed", unread: false, unreadCount: 0, escalationReason: undefined }
        : d,
    ),
  });
  persist(
    "Диалоги не закрылись",
    () => closeDialogsDb(ids),
    "Они остались открытыми — попробуйте ещё раз.",
  );
}

/** Начать диалог. Если окно закрыто, первым сообщением идёт только шаблон. */
/**
 * Написать пациенту первым.
 *
 * Асинхронна намеренно: раньше запись в базу шла «в фоне», а экран сразу
 * показывал «Сообщение отправлено». Отправка могла не состояться вовсе —
 * провайдер не принял, номера нет, в Instagram первым писать нельзя, — и
 * человек об этом не узнавал. Теперь результат ждём и показываем.
 */
export async function startDialog(input: {
  channel: DialogChannel;
  name: string;
  patientId: string | null;
  message: string;
}): Promise<{ ok: boolean; dialogId: string | null; error?: string }> {
  const id = uid("d");
  const messageId = uid("m");
  const dialog: Dialog = {
    id,
    name: input.name,
    channel: input.channel,
    patientId: input.patientId,
    // Диалог, заведённый из звонка: номер известен из карточки, а не из канала.
    phone: null,
    status: "human",
    preview: input.message,
    at: "сейчас",
    unread: false,
    windowOpen: true,
    windowMinutesLeft: null,
    messages: [{ id: messageId, from: "staff", text: input.message, at: "сейчас", attachments: [] }],
  };
  const res = await startDialogDb({
    id,
    messageId,
    channel: input.channel,
    patientId: input.patientId,
    message: input.message,
  }).catch((e) => {
    writeFailed("не удалось начать диалог")(e);
    return { ok: false, dialogId: null, error: (e as Error)?.message ?? "не удалось начать диалог" };
  });

  /**
   * Показываем диалог, только если сообщение действительно ушло. Строка в
   * списке при неудавшейся отправке — это ложь на экране: администратор
   * считает, что написал, и больше не возвращается к этому пациенту.
   */
  if (res.ok && res.dialogId) {
    /**
     * Сообщение могло лечь в УЖЕ существующую переписку — так и происходит,
     * когда пишут из «Кому позвонить» тому, с кем клиника давно говорит.
     * Тогда обновляем её, а не добавляем вторую строку с тем же
     * идентификатором: две строки об одном диалоге — это и сломанный список,
     * и два места, где искать ответ.
     */
    const id = res.dialogId;
    const known = db.dialogs.find((d) => d.id === id);
    const next: Dialog = known
      ? {
          ...known,
          status: "human",
          preview: input.message,
          at: "сейчас",
          unread: false,
          messages: [...known.messages, { id: messageId, from: "staff", text: input.message, at: "сейчас", attachments: [] }],
        }
      : { ...dialog, id };
    commit({ ...db, dialogs: [next, ...db.dialogs.filter((d) => d.id !== id)] });
  }
  return res;
}

// ─────────────────────────────────────────────── курсы (плоский список)

function daysSince(label: string): number | null {
  if (label === "сегодня") return 0;
  const m = /(\d+)\s+дн/.exec(label);
  return m ? Number(m[1]) : null;
}

export interface CourseView {
  patientId: string;
  patientName: string;
  channel: Channel;
  courseId: string;
  title: string;
  /** Сеансы, которые состоялись. */
  used: number;
  total: number;
  /** Не пройдено: по этим сеансам клиника ещё не отработала деньги. */
  remaining: number;
  /** Записан, но ещё не пришёл. */
  booked: number;
  /**
   * Сеансы, на которые пациент ещё НЕ записан.
   *
   * Именно это число отвечает на вопрос «кого звать». «Осталось 6» при шести
   * уже назначенных приёмах — повод для звонка человеку, который и так придёт
   * завтра.
   */
  toBook: number;
  status: Course["status"];
  lastVisit: string;
  daysAgo: number | null;
  hasFuture: boolean;
  moneyLeft: number;
  stalled: boolean;
  onFinish: boolean;
}

/** Плоский список курсов по всем пациентам с деньгами в остатке. */
/**
 * Курсы всех пациентов.
 *
 * Принимает список пациентов, а не читает модульный `db`: при рендере нужно
 * брать ровно тот снимок, что вернул useDb(). Иначе SSR считает по исходным
 * данным, а клиент к моменту гидратации уже видит подставленные из БД —
 * React ловит расхождение и перерисовывает поддерево заново.
 */
export function allCourses(patients: Patient[] = db.patients): CourseView[] {
  const out: CourseView[] = [];
  for (const p of patients) {
    for (const c of p.courses) {
      const remaining = Math.max(c.total - c.used, 0);
      const booked = c.booked ?? 0;
      const toBook = Math.max(remaining - booked, 0);
      const hasFuture = c.hasFuture ?? c.status !== "stalled";
      const price = c.pricePerSession ?? 0;
      out.push({
        patientId: p.id,
        patientName: p.name,
        channel: p.channel,
        courseId: c.id,
        title: c.title,
        used: c.used,
        total: c.total,
        remaining,
        booked,
        toBook,
        status: c.status,
        lastVisit: c.lastVisit,
        daysAgo: c.daysAgo ?? daysSince(c.lastVisit),
        hasFuture,
        moneyLeft: remaining * price,
        stalled: c.status === "stalled" && !hasFuture,
        // «Пора дозаписать» — про НЕзаписанные сеансы. Иначе экран звал бы
        // пациента, у которого оставшиеся приёмы уже стоят в расписании.
        onFinish: c.status === "active" && toBook > 0 && toBook <= 2,
      });
    }
  }
  return out;
}

/** Курс получил будущую запись — уходит из «выпавших». */
export function setCourseBooked(patientId: string, courseId: string) {
  replacePatient(patientId, (p) => ({
    ...p,
    courses: p.courses.map((c) =>
      c.id === courseId ? { ...c, hasFuture: true, status: c.status === "stalled" ? "active" : c.status } : c,
    ),
  }));
}

// ─────────────────────────────────────────────── расписание

function replaceAppt(id: string, fn: (a: Appt) => Appt) {
  commit({ ...db, appointments: db.appointments.map((a) => (a.id === id ? fn(a) : a)) });
}

export function markArrived(id: string) {
  replaceAppt(id, (a) => ({ ...a, status: "arrived" }));
  void setApptStatusDb(id, "arrived").catch(writeFailed("отметка «пришёл» не сохранена"));
}
/** Заметка по визиту после приёма. Её разбирает ИИ-аналитик владельца. */
export function setApptNote(id: string, note: string) {
  replaceAppt(id, (a) => ({ ...a, note: note.trim() || null }));
  void setApptNoteDb(id, note).catch(writeFailed("заметка по визиту не сохранена"));
}
/**
 * Проставить источник визита руками — отметка становится MANUAL, и выгрузка
 * её больше не трогает. Пустой код снимает отметку: это «не знаю», а не «звонок».
 */
export function setApptSource(id: string, code: string | null, title: string | null) {
  replaceAppt(id, (a) => ({
    ...a,
    sourceCode: code,
    sourceTitle: title,
    sourceConfidence: code ? "MANUAL" : "UNKNOWN",
  }));
  void setApptSourceDb(id, code).catch(writeFailed("источник визита не сохранён"));
}
export function markNoShow(id: string) {
  replaceAppt(id, (a) => ({ ...a, status: "no_show" }));
  void setApptStatusDb(id, "no_show").catch(writeFailed("отметка «не пришёл» не сохранена"));
}
export function rescheduleAppt(id: string, startMinute: number) {
  replaceAppt(id, (a) => ({ ...a, startMinute }));
  void rescheduleApptDb(id, startMinute).catch(writeFailed("перенос визита не сохранён"));
}
/**
 * Создать запись.
 *
 * `onError` обязателен по смыслу, а не по типу: раньше неудача записи в базу
 * гасилась пустым `catch`, и запись оставалась только на экране. Администратор
 * видел её в расписании, в YCLIENTS её не было — а значит, время считалось
 * свободным, и в него ставили второго пациента.
 */
export function addAppt(
  input: Omit<Appt, "id" | "status" | "isFirstVisit"> & { status?: Appt["status"] },
  onError?: (message: string) => void,
) {
  const appt: Appt = {
    id: uid("a"),
    status: input.status ?? "planned",
    isFirstVisit: false,
    ...input,
  };
  commit({ ...db, appointments: [...db.appointments, appt] });
  void createAppointmentDb({
    id: appt.id,
    // Кабинет — только выбранный. Подстановка первого приписывала запись
    // кабинету, в котором приёма нет, и портила его загрузку.
    roomId: appt.roomId ?? "",
    doctor: appt.doctor,
    staffId: appt.staffId ?? null,
    service: appt.service,
    patientId: appt.patientId,
    patientName: appt.patientName,
    startMinute: appt.startMinute,
    durationMin: appt.durationMin,
    status: appt.status,
    price: appt.price,
    note: appt.note,
    bookedByName: appt.bookedByName,
  }).catch((e: unknown) => {
    // Записи нет в базе — не должно быть и на экране.
    commit({ ...db, appointments: db.appointments.filter((a) => a.id !== appt.id) });
    const message = (e as Error)?.message ?? "не удалось сохранить запись";
    console.error("[запись] не сохранена:", message);
    onError?.(message);
  });
  return appt.id;
}
